export function sanitizeHTML(input, policy = {}) {
  let html = String(input ?? '');
  // remove script/style/iframe/object blocks
  html = html.replace(/<\s*(script|iframe|object|embed|style)\b[^>]*>[\s\S]*?<\s*\/\s*\1\s*>/gi, '');
  // remove self-closing/standalone dangerous tags
  html = html.replace(/<\s*\/?\s*(script|iframe|object|embed)\b[^>]*\/?\s*>/gi, '');
  // remove event handler attributes (quoted and unquoted)
  html = html.replace(/\s+on[a-zA-Z]+\s*=\s*"[^"]*"/gi, '');
  html = html.replace(/\s+on[a-zA-Z]+\s*=\s*'[^']*'/gi, '');
  html = html.replace(/\s+on[a-zA-Z]+\s*=\s*[^\s>]+/gi, '');
