  html = html.replace(/(href|src)\s*=\s*(["']?)\s*(?:javascript|vbscript|data)\s*:[^"'>\s]*\2/gi, '$1="#"');
  // any remaining javascript: literal
  html = html.replace(/javascript\s*:/gi, '');
  return html;
